SELECT
SUM(base.ybw_tb + base.ybyq_tb + base.ybwq_tb + base.wq_tb) AS count_tb,
ROUND(SUM(base.buy_budget_money), 2) AS money_tb,
SUM(base.ybw_tb) AS ybw_tb,
SUM(base.ybyq_tb) AS ybyq_tb,
SUM(base.ybwq_tb) AS ybwq_tb,
SUM(base.wq_tb) AS wq_tb,
SUM(base.ybw_zb + base.ybyq_zb + base.ybwq_zb + base.wq_zb) AS count_zb,
ROUND(SUM(base.match_bid_money), 2) AS money_zb,
SUM(base.ybw_zb) AS ybw_zb,
SUM(base.ybyq_zb) AS ybyq_zb,
SUM(base.ybwq_zb) AS ybwq_zb,
SUM(base.wq_zb) AS wq_zb
FROM (
SELECT
a.buy_budget_money,
a.match_bid_money,
IF(a.buy_budget_money < 100, 1, 0) AS ybw_tb,
IF(a.buy_budget_money >= 100 AND a.buy_budget_money < 1000, 1, 0) AS ybyq_tb,
IF(a.buy_budget_money >= 1000 AND a.buy_budget_money < 5000, 1, 0) AS ybwq_tb,
IF(a.buy_budget_money >= 5000, 1, 0) AS wq_tb,
IF(a.buy_budget_money < 100, 1, 0) AS ybw_zb,
IF(a.buy_budget_money >= 100 AND a.buy_budget_money < 1000, 1, 0) AS ybyq_zb,
IF(a.buy_budget_money >= 1000 AND a.buy_budget_money < 5000, 1, 0) AS ybwq_zb,
IF(a.buy_budget_money >= 5000, 1, 0) AS wq_zb
FROM topp_bid_new a
INNER JOIN topp_opportunity b ON a.opportunity_code = b.id_
INNER JOIN zqzt_sys_user c ON b.designer = c.user_id
INNER JOIN zqzt_sys_dept d ON c.dept_id = d.dept_id
WHERE d.dept_id IN (
SELECT dept_id FROM zqzt_sys_dept WHERE dept_id = #{tempDeptId}
UNION
SELECT t.dept_id FROM (SELECT * FROM zqzt_sys_dept WHERE parent_id IS NOT NULL) t,
(SELECT @parent_id := #{tempDeptId}) pd
WHERE FIND_IN_SET(parent_id, @parent_id) > 0
AND @parent_id := CONCAT(@parent_id, ',', dept_id)
)
AND a.is_sign = '0'

    AND a.buy_budget_money >= #{minCgAmount}


    AND a.buy_budget_money < #{maxCgAmount}


    AND a.match_bid_money >= #{minYjAmount}


    AND a.match_bid_money < #{maxYjAmount}


    AND b.expect_contract_money >= #{minSjAmount}


    AND b.expect_contract_money < #{maxSjAmount}


    AND a.bid_body IN

        #{item}



    AND a.competition_condition IN

        #{item}



    AND a.project_type IN

        #{item}



    AND a.result = #{bidResult}


    AND b.unicom_type IN

        #{item}



    AND a.ict_profit >= #{minMll}


    AND a.ict_profit <= #{maxMll}


    AND a.open_bid_time >= #{startTime}


    AND a.open_bid_time <= #{endTime}

) base

