SELECT base.nick_name AS user_name, SUM(base.ybw_tb) AS ybw_tb, SUM(base.ybyq_tb) AS ybyq_tb, SUM(base.ybwq_tb) AS ybwq_tb, SUM(base.wq_tb) AS wq_tb, SUM(base.ybw_tb + base.ybyq_tb + base.ybwq_tb + base.wq_tb) AS count_tb, ROUND(SUM(base.buy_budget_money), 2) AS money_tb, SUM(base.ybw_zb) AS ybw_zb, SUM(base.ybyq_zb) AS ybyq_zb, SUM(base.ybwq_zb) AS ybwq_zb, SUM(base.wq_zb) AS wq_zb, SUM(base.ybw_zb + base.ybyq_zb + base.ybwq_zb + base.wq_zb) AS count_zb, ROUND(SUM(base.match_bid_money), 2) AS money_zb, ROUND(SUM(base.match_bid_money * base.contribution / 100), 2) AS gxed_zb FROM ( SELECT d.nick_name, a.buy_budget_money, a.match_bid_money, c.contribution, CASE WHEN a.buy_budget_money < 100 THEN 1 ELSE 0 END AS ybw_tb, CASE WHEN a.buy_budget_money BETWEEN 100 AND 999 THEN 1 ELSE 0 END AS ybyq_tb, CASE WHEN a.buy_budget_money BETWEEN 1000 AND 4999 THEN 1 ELSE 0 END AS ybwq_tb, CASE WHEN a.buy_budget_money >= 5000 THEN 1 ELSE 0 END AS wq_tb, CASE WHEN a.buy_budget_money < 100 THEN 1 ELSE 0 END AS ybw_zb, CASE WHEN a.buy_budget_money BETWEEN 100 AND 999 THEN 1 ELSE 0 END AS ybyq_zb, CASE WHEN a.buy_budget_money BETWEEN 1000 AND 4999 THEN 1 ELSE 0 END AS ybwq_zb, CASE WHEN a.buy_budget_money >= 5000 THEN 1 ELSE 0 END AS wq_zb FROM topp_bid_new a INNER JOIN topp_opportunity b ON a.opportunity_code = b.id_ LEFT JOIN zqzt_sys_user d ON b.designer = d.user_id LEFT JOIN zqzt_sys_dept e ON d.dept_id = e.dept_id LEFT JOIN topp_bid_new_score c ON a.id = c.topp_bid_new_id AND c.name = d.nick_name WHERE e.dept_id = #{deptId} AND a.is_sign = '0'
AND a.buy_budget_money >= #{minCgAmount}
AND a.buy_budget_money < #{maxCgAmount}
AND a.match_bid_money >= #{minYjAmount}
AND a.match_bid_money < #{maxYjAmount}
AND b.expect_contract_money >= #{minSjAmount}
AND b.expect_contract_money < #{maxSjAmount}
AND a.bid_body IN
#{item}
AND a.competition_condition IN
#{item}
AND a.project_type IN
#{item}
AND a.result = #{bidResult}
AND b.unicom_type IN
#{item}
AND a.ict_profit >= #{minMll}
AND a.ict_profit <= #{maxMll}
AND a.open_bid_time >= #{startTime}
AND a.open_bid_time <= #{endTime}
) base GROUP BY base.nick_name

