SELECT
base.nick_name AS user_name,
SUM(base.ybw_qy + base.ybyq_qy + base.ybwq_qy + base.wq_qy) AS count_qy,
ROUND(SUM(base.sign_money), 2) AS money_qy,
SUM(base.ybw_qy) AS ybw_qy,
SUM(base.ybyq_qy) AS ybyq_qy,
SUM(base.ybwq_qy) AS ybwq_qy,
SUM(base.wq_qy) AS wq_qy,
ROUND(SUM(base.sign_money * base.contribution / 100), 2) AS gxed_money
FROM (
SELECT
d.nick_name,
a.sign_money,
c.contribution,
CASE WHEN a.sign_money < 100 THEN 1 ELSE 0 END AS ybw_qy,
CASE WHEN a.sign_money BETWEEN 100 AND 999 THEN 1 ELSE 0 END AS ybyq_qy,
CASE WHEN a.sign_money BETWEEN 1000 AND 4999 THEN 1 ELSE 0 END AS ybwq_qy,
CASE WHEN a.sign_money >= 5000 THEN 1 ELSE 0 END AS wq_qy
FROM topp_bid_new a
INNER JOIN topp_opportunity b ON a.opportunity_code = b.id_
INNER JOIN topp_bid_new_score c ON a.id = c.topp_bid_new_id
LEFT JOIN zqzt_sys_user d ON b.designer = d.user_id
LEFT JOIN zqzt_sys_dept e ON d.dept_id = e.dept_id
WHERE e.dept_id = #{deptId}
AND a.is_sign = '1'
AND c.name = d.nick_name

    AND a.buy_budget_money >= #{minCgAmount}


    AND a.buy_budget_money < #{maxCgAmount}


    AND a.sign_money >= #{minYjAmount}


    AND a.sign_money < #{maxYjAmount}


    AND b.expect_contract_money >= #{minSjAmount}


    AND b.expect_contract_money < #{maxSjAmount}


    AND a.bid_body IN

        #{item}



    AND a.competition_condition IN

        #{item}



    AND a.project_type IN

        #{item}



    AND a.result = #{bidResult}


    AND b.unicom_type IN

        #{item}



    AND a.ict_profit >= #{minMll}


    AND a.ict_profit <= #{maxMll}


    AND a.open_bid_time >= #{startTime}


    AND a.open_bid_time <= #{endTime}

) base
GROUP BY base.nick_name
